// Open-source licences of the bundled packages (T-154). Generated by scripts/gen-licences.js.
export interface LicenceEntry {
  /** "name@version" */
  pkg: string;
  licenses: string;
  repository?: string;
}

interface RawEntry {
  licenses: string;
  repository?: string;
}

export function parseLicences(raw: Record<string, RawEntry>): LicenceEntry[] {
  return Object.entries(raw)
    .map(([pkg, v]) => ({ pkg, licenses: v.licenses, repository: v.repository }))
    .sort((a, b) => a.pkg.localeCompare(b.pkg));
}

export function loadLicences(): LicenceEntry[] {
  const raw = require('../../../../assets/licences.json') as Record<string, RawEntry>;
  return parseLicences(raw);
}
